def _seed_thinking_methods() -> None:
    """Seed the administrator-managed mathematical methods catalog."""
    connection = op.get_bind()
    now = datetime.now(timezone.utc).replace(tzinfo=None)
    category_table = sa.table(
        "thinking_method_categories",
        *(sa.column(name) for name in (
            "code", "label", "symbol", "focus", "description", "reminder",
            "sort_order", "status", "version_lock", "created_at", "updated_at",
        )),
    )
    category_rows = [dict(item, created_at=now, updated_at=now) for item in _THINKING_CATEGORIES]
    connection.execute(category_table.insert(), category_rows)
    category_ids = dict(connection.execute(sa.text("SELECT code, id FROM thinking_method_categories")).all())
    method_table = sa.table(
        "thinking_methods",
        sa.column("code"), sa.column("category_id"), sa.column("parent_method_id"),
        sa.column("name"), sa.column("kind"), sa.column("level"), sa.column("goal"),
        sa.column("example"), sa.column("grade_bands_json", sa.JSON()),
        sa.column("domain_tags_json", sa.JSON()), sa.column("aliases_json", sa.JSON()),
        sa.column("detail_json", sa.JSON()), sa.column("sort_order"), sa.column("status"),
        sa.column("version_lock"), sa.column("created_at"), sa.column("updated_at"),
    )
    method_rows = []
    for item in _THINKING_METHODS:
        row = dict(item)
        row["category_id"] = category_ids[row.pop("category_code")]
        row["parent_method_id"] = None
        row["created_at"] = now
        row["updated_at"] = now
        method_rows.append(row)
    connection.execute(method_table.insert(), method_rows)


